import React from "react";
import { Audio, staticFile } from "remotion";

/** Sound effects generated by scripts/make_audio.py into public/sfx. */
export type SfxKind = "click" | "pop" | "whoosh" | "impact" | "ding" | "type" | "riser" | "cut" | "lock" | "swish";

const VOLUME: Record<SfxKind, number> = {
  click: 0.55,
  pop: 0.5,
  whoosh: 0.45,
  impact: 0.7,
  ding: 0.45,
  type: 0.35,
  riser: 0.5,
  cut: 0.45,
  lock: 0.55,
  swish: 0.4,
};

export const Sfx: React.FC<{ kind: SfxKind }> = ({ kind }) => <Audio src={staticFile(`sfx/${kind}.wav`)} volume={VOLUME[kind]} />;

export const Music: React.FC<{ src: string; volume?: number }> = ({ src, volume = 0.8 }) => <Audio src={staticFile(src)} volume={volume} />;
